package com.asmj.marketplace.event.controller; import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.event.controller.EventDtos.*;import com.asmj.marketplace.event.service.EventMarketplaceService;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/events") @RequiredArgsConstructor public class EventController{final EventMarketplaceService s;String e(Authentication a){return a.getName();}@GetMapping public ApiResponse<?> all(){return ApiResponse.ok("",s.publicEvents());}@PreAuthorize("hasRole('VENDOR')") @GetMapping("/vendor") public ApiResponse<?> vendor(Authentication a){return ApiResponse.ok("",s.vendorEvents(e(a)));}@PreAuthorize("hasRole('VENDOR')") @PostMapping("/vendor") public ApiResponse<?> create(Authentication a,@RequestBody EventRequest r){return ApiResponse.ok("",s.save(e(a),r,null));}@PreAuthorize("hasRole('VENDOR')") @PutMapping("/vendor/{id}") public ApiResponse<?> edit(Authentication a,@PathVariable String id,@RequestBody EventRequest r){return ApiResponse.ok("",s.save(e(a),r,id));}@PreAuthorize("hasAnyRole('USER','VENDOR','ADMIN')") @PostMapping("/{id}/register") public ApiResponse<?> register(Authentication a,@PathVariable String id,@RequestBody RegistrationRequest r){return ApiResponse.ok("",s.register(e(a),id,r));}@PreAuthorize("isAuthenticated()") @GetMapping("/registrations/my") public ApiResponse<?> my(Authentication a){return ApiResponse.ok("",s.my(e(a)));}@PreAuthorize("hasAnyRole('VENDOR','ADMIN')") @GetMapping("/registrations/vendor") public ApiResponse<?> vr(Authentication a){return ApiResponse.ok("",s.vendorRegistrations(e(a)));}@PreAuthorize("isAuthenticated()") @PostMapping("/registrations/{id}/cancel") public ApiResponse<?> cancel(Authentication a,@PathVariable String id){return ApiResponse.ok("",s.cancel(e(a),id));}}
